   if(ph.pb.length===4){if(ph.pb===PINS[BK]){ph.pb='';SAL[BK]-=ph.fat.v;ph.fat.paid=1;ph.fat.bk=BK;LEDGER.push({f:fi,bk:BK,n:'Fatura do cartão',b:'pago por '+({pix:'Pix',boleto:'boleto',debito:'débito em conta'})[ph.fat.forma],v:ph.fat.v,ok:true,h:new Date().toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})});dash();go('fat-ok');return}ph.pb='';toast('Senha incorreta')}
