  if(a==='inv-sim'){var iv=parse($('inV').value),im=parseInt($('inM').value,10);if(!(iv>0))return toast('Digite um valor válido');if(!(im>=1&&im<=120))return toast('Prazo de 1 a 120 meses');ph.iv=Math.round(iv*100);ph.im=im;return draw()}
  if(a==='inv-ap'){var iv2=parse($('inV').value),im2=parseInt($('inM').value,10);if(!(iv2>0))return toast('Digite um valor válido');var c2=Math.round(iv2*100);if(c2>sal())return toast('Saldo insuficiente neste banco');if(BLOQ[BK])return toast('Conta bloqueada. Cubra o negativo primeiro.');SAL[BK]-=c2;INV[BK]=(INV[BK]||0)+c2;dash();toast('Aplicado! Você pode resgatar quando quiser.');return go('inv')}
  if(a==='inv-rg'){var rv=INV[BK]||0;if(rv<=0)return;SAL[BK]+=rv;INV[BK]=0;dash();toast('Resgatado '+fmt(rv)+' para a conta.');return go('inv')}
  if(a==='extr')return go('extr');
